// ─── Transcript bubble grouping ──────────────────────────────────────
// Streaming transcripts arrive as fragments — "Got" / "it." / "When did" —
// because the agent_text_buf flushes on phrase boundaries. Group them into
// chat-bubble-shaped utterances: a new bubble starts when role changes, or
// when the previous bubble ended in terminal punctuation (. ? !), or after
// a long enough gap that it's clearly a new thought.

export type TranscriptBubble = {
  id: string;            // first message id (stable React key)
  role: "agent" | "caller";
  source: string | null;
  text: string;          // joined fragments
  firstTimestamp: string;
  lastTimestamp: string;
};

const TERMINAL_PUNCTUATION = /[.!?。！？]\s*$/;
const MAX_FRAGMENT_GAP_MS = 3000;

export function groupTranscriptBubbles(messages: Message[]): TranscriptBubble[] {
  const bubbles: TranscriptBubble[] = [];
  for (const m of messages) {
    const last = bubbles[bubbles.length - 1];
    const text = m.text.trim();
    if (!text) continue;

    const sameRole = last && last.role === m.role;
    const lastEnded = last && TERMINAL_PUNCTUATION.test(last.text);
    const gapMs = last
      ? Date.parse(m.timestamp) - Date.parse(last.lastTimestamp)
      : Infinity;

    if (sameRole && !lastEnded && gapMs < MAX_FRAGMENT_GAP_MS) {
      // Continuation of previous fragment — joint with a space, but don't
      // double-space if the new fragment starts with punctuation.
      const sep = /^[,.!?;:。！？，；：]/.test(text) ? "" : " ";
      last.text = (last.text + sep + text).replace(/\s+/g, " ").trim();
      last.lastTimestamp = m.timestamp;
    } else {
      bubbles.push({
        id: m.id,
        role: m.role,
        source: m.source ?? null,
        text,
        firstTimestamp: m.timestamp,
        lastTimestamp: m.timestamp,
      });
    }
  }
  return bubbles;
}

