/* ─── FNOL field rows ─────────────────────────────────────────────── */
.fnol-row {
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 16px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  font-size: 13px;
}
.fnol-row:last-child { border-bottom: none; }
.fnol-label { color: var(--text-tertiary); font-size: 12px; letter-spacing: 0.02em; }
.fnol-value { color: var(--text-primary); }
.fnol-value.is-pending {
  color: var(--text-quaternary);
  font-style: italic;
}
.show-more {
  margin-top: 14px;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  padding: 8px 0;

