.fnol-value.is-pending {
  color: var(--text-quaternary);
  font-style: italic;
}
.fnol-value.editable {
  cursor: text;
  border-bottom: 1px dashed transparent;
  transition: border-color 0.15s ease, background 0.15s ease;
  padding: 1px 4px;
  margin: -1px -4px;
  border-radius: 3px;
}
.fnol-value.editable:hover,
.fnol-value.editable:focus {
  border-bottom-color: rgba(255,255,255,0.20);
  background: rgba(255,255,255,0.03);
  outline: none;
}
.fnol-edit {
  display: flex;
  align-items: center;
  gap: 8px;
}
.fnol-input {
  flex: 1;
  min-width: 0;
  background: rgba(0,0,0,0.30);
  color: var(--text-primary);
  border: 1px solid rgba(50,215,75,0.30);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 13px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease;
}
.fnol-input:focus {
  border-color: rgba(50,215,75,0.60);
  box-shadow: 0 0 0 2px rgba(50,215,75,0.10);
}
.fnol-input:disabled {
  opacity: 0.5;
  cursor: wait;
}
.fnol-error {
  color: #ff6b6b;
  font-family: var(--font-mono), monospace;
  font-size: 11px;
  font-weight: 700;
  cursor: help;
}

