  font-size: 11px;
  color: var(--text-tertiary);
  font-family: var(--font-mono), monospace;
  letter-spacing: 0.04em;
}
.arch-bar-totalrow code {
  font-family: var(--font-mono), monospace;
  background: rgba(0,0,0,0.25);
  padding: 1px 6px;
  border-radius: 3px;
  color: var(--text-secondary);
}
.arch-bar-footnote {
  font-size: 12px;
  color: var(--text-tertiary);
  line-height: 1.6;
  font-style: italic;
  margin: 0;
  max-width: 70ch;
}

/* Comparison table */
.arch-table {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.arch-table-row {
  display: grid;
  grid-template-columns: 1.6fr 1.7fr 1.7fr;
  gap: 18px;
  padding: 14px 18px;
  border-radius: 6px;
  align-items: center;
  font-size: 13px;
  transition: background 0.15s ease;
}
.arch-table-row:hover { background: rgba(255,255,255,0.03); }
.arch-table-head {
  font-family: var(--font-mono), monospace;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  padding-bottom: 12px;
  margin-bottom: 4px;
}
.arch-table-cap {
  color: var(--text-primary);
  font-weight: 500;
}
.arch-table-half { color: var(--text-tertiary); }
.arch-table-full { color: rgba(50,215,75,0.92); }

/* Benchmark grid */
.arch-bench-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}
@media (max-width: 900px) {
  .arch-bench-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 600px) {
  .arch-bench-grid { grid-template-columns: 1fr; }
}
.arch-bench {
  padding: 22px 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: border-color 0.2s ease;
}
.arch-bench:hover { border-color: rgba(50,215,75,0.20); }
.arch-bench-label {
  font-family: var(--font-mono), monospace;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-tertiary);
}
.arch-bench-value {
  font-size: 28px;
  color: var(--text-primary);
  font-weight: 300;
  letter-spacing: -0.02em;
  line-height: 1.1;
}
.arch-bench-context {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* Why-this-matters */
.arch-why { display: flex; flex-direction: column; gap: 22px; }
.arch-why-item { display: flex; gap: 22px; align-items: flex-start; }
.arch-why-num {
  font-family: var(--font-mono), monospace;
  font-size: 24px;
  color: rgba(50,215,75,0.45);
  font-weight: 300;
  line-height: 1;
  letter-spacing: 0.02em;
  flex-shrink: 0;
  width: 48px;
}
.arch-why-h {
  font-size: 15px;
  color: var(--text-primary);
  margin: 0 0 6px;
  font-weight: 500;
}
.arch-why-p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin: 0;
  max-width: 70ch;
}
